const items = $input.all();

// Función para limpiar texto (quitar comillas y saltos de línea para ManyChat)
function cleanTextForManyChat(text) {
  // Asegurar que text es string
  const textStr = typeof text === 'string' ? text : String(text);

  return textStr
    // Quita cualquier salto de línea (uno o varios seguidos)
    .replace(/\n+/g, ' ')
    // Quita todas las comillas dobles
    .replace(/"/g, '')
    // Limpia espacios múltiples que puedan quedar
    .replace(/\s+/g, ' ')
    // Quita espacios al inicio y final
    .trim();
}

const processedItems = [];

items.forEach(item => {
  const aiResponse = item.json.output;

  // Verificar si ya es un objeto (JSON parseado)
  if (typeof aiResponse === 'object' && aiResponse !== null) {
    // Ya es un objeto JSON parseado
    if (Array.isArray(aiResponse)) {
      // Si aiResponse es directamente un array (el caso del structured parser)
      aiResponse.forEach((message, index) => {
        processedItems.push({
          json: {
            output: cleanTextForManyChat(message),
            messageIndex: index + 1,
            totalMessages: aiResponse.length,
            originalItemIndex: items.indexOf(item)
          }
        });
      });
    } else if (aiResponse.output && Array.isArray(aiResponse.output)) {
      // Si tiene la estructura {output: [...]}
      aiResponse.output.forEach((message, index) => {
        processedItems.push({
          json: {
            output: cleanTextForManyChat(message),
            messageIndex: index + 1,
            totalMessages: aiResponse.output.length,
            originalItemIndex: items.indexOf(item)
          }
        });
      });
    } else if (aiResponse.messages && Array.isArray(aiResponse.messages)) {
      // Compatibilidad con formato anterior {messages: [...]}
      aiResponse.messages.forEach((message, index) => {
        processedItems.push({
          json: {
            output: cleanTextForManyChat(message),
            messageIndex: index + 1,
            totalMessages: aiResponse.messages.length,
            originalItemIndex: items.indexOf(item)
          }
        });
      });
    } else {
      // Si es objeto pero no tiene el formato correcto, convertir a string y limpiar
      processedItems.push({
        json: {
          output: cleanTextForManyChat(JSON.stringify(aiResponse)),
          messageIndex: 1,
          totalMessages: 1,
          originalItemIndex: items.indexOf(item)
        }
      });
    }
  } else {
    // Es string, intentar parsearlo como JSON
    try {
      const parsed = JSON.parse(aiResponse);

      if (Array.isArray(parsed)) {
        // Si el JSON parseado es directamente un array
        parsed.forEach((message, index) => {
          processedItems.push({
            json: {
              output: cleanTextForManyChat(message),
              messageIndex: index + 1,
              totalMessages: parsed.length,
              originalItemIndex: items.indexOf(item)
            }
          });
        });
      } else if (parsed.output && Array.isArray(parsed.output)) {
        // Si tiene la estructura {output: [...]}
        parsed.output.forEach((message, index) => {
          processedItems.push({
            json: {
              output: cleanTextForManyChat(message),
              messageIndex: index + 1,
              totalMessages: parsed.output.length,
              originalItemIndex: items.indexOf(item)
            }
          });
        });
      } else if (parsed.messages && Array.isArray(parsed.messages)) {
        // Compatibilidad con formato anterior {messages: [...]}
        parsed.messages.forEach((message, index) => {
          processedItems.push({
            json: {
              output: cleanTextForManyChat(message),
              messageIndex: index + 1,
              totalMessages: parsed.messages.length,
              originalItemIndex: items.indexOf(item)
            }
          });
        });
      } else {
        // Si el JSON no tiene el formato correcto, tratar como mensaje único
        processedItems.push({
          json: {
            output: cleanTextForManyChat(aiResponse),
            messageIndex: 1,
            totalMessages: 1,
            originalItemIndex: items.indexOf(item)
          }
        });
      }
    } catch (error) {
      // Si no es JSON válido, procesar como mensaje único y limpiar
      processedItems.push({
        json: {
          output: cleanTextForManyChat(aiResponse),
          messageIndex: 1,
          totalMessages: 1,
          originalItemIndex: items.indexOf(item)
        }
      });
    }
  }
});

return processedItems;

